// A multi-series bar chart: one row per category, one cell per series, and the bar is the cell's own background — as wide as
// the value's share of the scale, with left padding of the same width so the number starts where the bar ends. The markup is
// a table: the column headers are the legend (each with a checkbox that hides its series), every number is the cell's text,
// and the colours are decoration over the numbers a reader already hears.
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createSignal, createUniqueId, For } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the table, `data-part` and the caller's class merged in. */
export type BarsPartProps = PartProps;

/** One series: its key, which the caller hides it by, and the name the legend shows. */
export interface BarsSeries {
  readonly key: string;
  readonly label: string;
}

export interface BarsProps extends Renderable<BarsPartProps, void> {
  /** The series, in reading order; each is a column and a legend entry. */
  readonly series: ReadonlyArray<BarsSeries>;
  /** The categories, one row each. */
  readonly categories: ReadonlyArray<string>;
  /** The values, one row per category and one number per series; a missing number is an empty cell. */
  readonly values: ReadonlyArray<ReadonlyArray<number>>;
  /** The table's caption, which also names the chart: "Response time by region". */
  readonly label: string;
  /** The top of the scale; left out, the largest value. */
  readonly max?: number;
  /** A value as a reader sees it; left out, the number itself. */
  readonly format?: (value: number) => string;
  /** The series keys to hide; with `onHiddenChange`, the page owns this, otherwise it only seeds the component. */
  readonly hidden?: ReadonlyArray<string>;
  /** Called with the new set when a legend box moves; given, the component reads `hidden` instead of its own state. */
  readonly onHiddenChange?: (hidden: ReadonlyArray<string>) => void;
  readonly class?: string;
}

// The bar's paint: the highlight at a fifth of its strength, over the surface. One tint for every series — the columns and
// their headers carry the series, so colour never has to, and a number that runs under a long bar still reads.
const BAR = css.colorMix("in oklab", [t.color.highlight, "22%"], t.color.surface);

// Every row is a grid of its own with the same tracks (the label, then one per series), so a hidden cell leaves no hole and
// the columns stay aligned across the sections: the tracks are the row's, not the whole table's.
const table = css.cn(
  css.display("block"),
  css.width("100%"),
  css.borderCollapse("collapse"),
  css.fontSize(t.font.size),
  css.color(t.color.text),
);

const caption = css.cn(
  css.display("block"),
  css.paddingBlock(t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);
const head = css.cn(css.display("block"));
const body = css.cn(css.display("block"));
const row = css.cn(css.display("grid"), css.alignItems("center"), css.group());

// The header row is the legend: a checkbox that hides its series, and the name.
const seriesHead = css.cn(
  css.padding("2px 0"),
  css.paddingInlineEnd(t.space._2),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("400"),
  css.color(t.color.muted),
  css.textAlign("start"),
);
const legend = css.cn(
  css.display("inline-flex"),
  css.alignItems("center"),
  css.gap(t.space._1),
  css.cursor("pointer"),
  css.minWidth("0"),
  css.overflowWrap("anywhere"),
);
const box = css.cn(
  css.accentColor(t.color.highlight),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const label = css.cn(
  css.paddingBlock("0.15rem"),
  css.paddingInlineEnd(t.space._2),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.textAlign("start"),
  css.overflowWrap("anywhere"),
  css.within(css.hover)(css.color(t.color.textHover)),
);

// One bar. The value's share of the scale is the background's width, and the same width of left padding moves the number
// past the bar's end. `min()` stops a long label leaving the plot: a bar longer than the room the label needs runs under it
// instead, which is why the bar is a tint and not a solid.
const cell = css.cn(
  css.paddingBlock("0.15rem"),
  css.paddingInlineEnd(t.space._1),
  css.paddingInlineStart("min(calc(var(--v) / var(--max) * 100% + 0.35rem), calc(100% - 4.5rem))"),
  css.fontSize(t.font.sizeSm),
  css.fontVariantNumeric("tabular-nums"),
  css.minWidth("0"),
  css.overflowWrap("anywhere"),
  css.borderRadius("2px"),
  css.backgroundImage(css.linearGradient(BAR, BAR)),
  css.backgroundRepeat("no-repeat"),
  css.backgroundPosition("0 50%"),
  // the bar's own gap is drawn inside it, so the row's hover area is one strip and nothing flickers between cells
  css.backgroundSize("calc(var(--v) / var(--max) * 100%) calc(100% - 0.25rem)"),
  css.transition("background-color 120ms"),
  css.within(css.hover)(css.backgroundColor(t.color.buttonBackground)),
);

const frame = css.cn(css.display("grid"), css.width("100%"), css.margin(0));

const number = (value: number): string => String(value);

/**
 * A multi-series bar chart: one row per category, one bar per series, each bar a background sized by its value.
 *
 * The header row is the legend: its checkboxes hide a column, and because the hiding is state the component (or the page)
 * owns, the hidden cells leave the table too instead of sitting there empty. The numbers are the cells' text, so the chart
 * reads without a pointer, and with the stylesheet off it is the table underneath.
 */
export const Bars = (props: BarsProps): JSX.Element => {
  const base = createUniqueId();
  const [ownHidden, setOwnHidden] = createSignal<ReadonlyArray<string>>(props.hidden ?? []);
  // the page owns the state when it gave a handler; otherwise the component does, seeded by `hidden`
  const hidden = (): ReadonlyArray<string> =>
    props.onHiddenChange ? (props.hidden ?? []) : ownHidden();
  const isHidden = (key: string): boolean => hidden().includes(key);
  const toggle = (key: string, shown: boolean): void => {
    const next = shown ? hidden().filter((entry) => entry !== key) : [...hidden(), key];
    if (props.onHiddenChange) {
      props.onHiddenChange(next);
    } else {
      setOwnHidden(next);
    }
  };
  const top = (): number => {
    const largest = props.max ?? Math.max(0, ...props.values.flat());
    // one scale for a flat chart, so a bar with no height does not divide by nothing
    return largest <= 0 ? 1 : largest;
  };
  const show = (value: number): string => (props.format ?? number)(value);
  // the tracks every row shares: the label column, then one per series that is still shown
  const shown = (): number =>
    Math.max(1, props.series.filter((series) => !isHidden(series.key)).length);
  const tracks = (): string => `min(7rem, 30%) repeat(${shown()}, minmax(0, 1fr))`;
  // the header's id ties a cell to its series for a reader; the key only has to be unique within this chart
  const headerId = (key: string): string => `${base}-${key.replace(/[^a-zA-Z0-9_-]/g, "-")}`;

  const own = {
    "data-part": "bars",
    get class() {
      return css.cn(table, props.class);
    },
    get style() {
      return { "--max": top() } as never;
    },
  } as unknown as PartProps;

  return (
    <figure data-part="bars-frame" class={frame}>
      {renderPart(props, own, undefined, (part) => (
        <table {...part}>
          <caption class={caption}>{props.label}</caption>
          <thead class={head}>
            <tr class={row} style={{ "grid-template-columns": tracks() } as never}>
              {/* the corner is the grid's first cell and says nothing: the row headers name the rows */}
              <td aria-hidden="true" />
              <For each={props.series}>
                {(series) => (
                  <th
                    scope="col"
                    id={headerId(series.key)}
                    data-part="bars-series"
                    data-series={series.key}
                    class={seriesHead}
                    hidden={isHidden(series.key)}
                  >
                    <label class={legend}>
                      <input
                        type="checkbox"
                        class={box}
                        checked={!isHidden(series.key)}
                        onChange={(event) => toggle(series.key, event.currentTarget.checked)}
                      />
                      {series.label}
                    </label>
                  </th>
                )}
              </For>
            </tr>
          </thead>
          <tbody class={body}>
            <For each={props.categories}>
              {(category, line) => (
                <tr class={row} style={{ "grid-template-columns": tracks() } as never}>
                  <th scope="row" class={label}>
                    {category}
                  </th>
                  <For each={props.series}>
                    {(series, column) => {
                      const value = (): number | undefined => props.values[line()]?.[column()];
                      return (
                        <td
                          data-part="bars-cell"
                          data-series={series.key}
                          headers={headerId(series.key)}
                          class={cell}
                          hidden={isHidden(series.key)}
                          style={{ "--v": value() ?? 0 } as never}
                        >
                          {value() === undefined ? "" : show(value() as number)}
                        </td>
                      );
                    }}
                  </For>
                </tr>
              )}
            </For>
          </tbody>
        </table>
      ))}
    </figure>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The bar chart's conformance: the table is the data, the bars are backgrounds, and the legend is the header row. The tests
// read what a reader gets — a caption, a header per series, a cell per pair with its number and its header, and the widths
// the values ask for — and what the legend does to the table, not the stylesheet that draws it.
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { createSignal } from "solid-js";
import { describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { Bars, type BarsSeries } from "./bars.tsx";

const mount = (element: () => JSX.Element) => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(element, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const SERIES: ReadonlyArray<BarsSeries> = [
  { key: "eu", label: "eu-west" },
  { key: "us", label: "us-east" },
  { key: "ap", label: "ap-south" },
];
const CATEGORIES = ["Mon", "Tue"];
const VALUES = [
  [10, 40, 20],
  [20, 10, 40],
];

const headers = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="bars-series"]'),
];
const cells = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="bars-cell"]'),
];
const table = (root: HTMLElement): HTMLElement =>
  root.querySelector<HTMLElement>('[data-part="bars"]')!;
// the bar's width is a percentage of the cell, which is what `background-size` keeps; the padding beside it resolves to px
const share = (cell: HTMLElement): number =>
  Number.parseFloat(getComputedStyle(cell).backgroundSize);
const start = (cell: HTMLElement): number =>
  Number.parseFloat(getComputedStyle(cell).paddingInlineStart);

describe("Bars", () => {
  it("is a table: a caption, a legend per series, a cell per pair with its number", () => {
    const { root, dispose } = mount(() => (
      <Bars label="Requests by region" series={SERIES} categories={CATEGORIES} values={VALUES} />
    ));
    // the caption names the chart
    expect(root.querySelector("caption")?.textContent).toBe("Requests by region");
    // the header row is the legend: one named, checked box per series
    expect(headers(root).map((head) => head.textContent?.trim())).toEqual([
      "eu-west",
      "us-east",
      "ap-south",
    ]);
    for (const head of headers(root)) {
      expect(head.querySelector("input[type=checkbox]")).toHaveProperty("checked", true);
    }
    // one row header per category, one cell per pair, and the number is the cell's text
    expect(root.querySelectorAll('th[scope="row"]')).toHaveLength(2);
    expect(cells(root).map((cell) => cell.textContent?.trim())).toEqual([
      "10",
      "40",
      "20",
      "20",
      "10",
      "40",
    ]);
    // every cell is tied to its series' header, so a reader hears which series the number is
    const ids = headers(root).map((head) => head.id);
    expect(cells(root).map((cell) => cell.getAttribute("headers"))).toEqual([
      ids[0],
      ids[1],
      ids[2],
      ids[0],
      ids[1],
      ids[2],
    ]);
    dispose();
  });

  it("paints each bar as wide as its share of the scale, and starts the number where it ends", () => {
    const { root, dispose } = mount(() => (
      <Bars label="Requests" series={SERIES} categories={CATEGORIES} values={VALUES} />
    ));
    const [low, high, middle] = cells(root);
    // the scale is the data's largest value unless the page gives one
    expect(table(root).style.getPropertyValue("--max")).toBe("40");
    expect(share(high!)).toBe(100);
    expect(share(middle!)).toBe(50);
    expect(share(low!)).toBe(25);
    // a background, not an element: the bar is the cell's own paint
    expect(getComputedStyle(high!).backgroundImage).toContain("linear-gradient");
    // the number starts just past the bar, because the padding is the same share of the cell (plus the gap)
    expect(start(low!)).toBeCloseTo(
      (low!.getBoundingClientRect().width * share(low!)) / 100 + 5.6,
      0,
    );
    dispose();
  });

  it("takes the page's scale, its formatting and a missing value", () => {
    const { root, dispose } = mount(() => (
      <Bars
        label="Requests"
        series={SERIES}
        categories={CATEGORIES}
        values={[
          [10, 20, 40],
          [20, 10],
        ]}
        max={80}
        format={(value) => `${value} req`}
      />
    ));
    expect(table(root).style.getPropertyValue("--max")).toBe("80");
    expect(cells(root)[0]?.textContent?.trim()).toBe("10 req");
    // a missing number is an empty cell, not a zero the page never gave
    expect(cells(root)[5]?.textContent?.trim()).toBe("");
    expect(cells(root)[5]?.style.getPropertyValue("--v")).toBe("0");
    // the page's scale is what the bar is a share of
    expect(share(cells(root)[0]!)).toBe(12.5);
    dispose();
  });

  it("hides a series in the table itself when its legend box is unchecked", async () => {
    const { root, dispose } = mount(() => (
      <Bars label="Requests" series={SERIES} categories={CATEGORIES} values={VALUES} />
    ));
    const us = headers(root)[1]!;
    const box = us.querySelector<HTMLInputElement>("input[type=checkbox]")!;
    await userEvent.click(box);

    // the header leaves the table with its column: no empty cells are left lying to a reader
    expect(us.hidden).toBe(true);
    expect(box.checked).toBe(false);
    const gone = cells(root).filter((cell) => cell.dataset["series"] === "us");
    expect(gone).toHaveLength(2);
    for (const cell of gone) {
      expect(cell.hidden).toBe(true);
    }
    // the telling cells stay, with their numbers and their own headers
    const stays = cells(root).filter((cell) => cell.dataset["series"] === "eu");
    expect(stays.every((cell) => !cell.hidden)).toBe(true);
    expect(stays.map((cell) => cell.textContent?.trim())).toEqual(["10", "20"]);

    // a series the page starts hidden is not in the table either
    const other = mount(() => (
      <Bars
        label="Requests"
        series={SERIES}
        categories={CATEGORIES}
        values={VALUES}
        hidden={["ap"]}
      />
    ));
    expect(headers(other.root)[2]?.hidden).toBe(true);
    expect(cells(other.root).filter((cell) => cell.hidden)).toHaveLength(2);
    other.dispose();
    dispose();
  });

  it("reads the hidden set from the page when the page owns it", async () => {
    const [hidden, setHidden] = createSignal<ReadonlyArray<string>>([]);
    const { root, dispose } = mount(() => (
      <Bars
        label="Requests"
        series={SERIES}
        categories={CATEGORIES}
        values={VALUES}
        hidden={hidden()}
        onHiddenChange={setHidden}
      />
    ));
    await userEvent.click(headers(root)[0]!.querySelector("input[type=checkbox]")!);
    // the page's signal is the one that moved, and the table followed it
    expect(hidden()).toEqual(["eu"]);
    expect(headers(root)[0]?.hidden).toBe(true);
    expect(
      cells(root)
        .filter((cell) => cell.dataset["series"] === "eu")
        .every((c) => c.hidden),
    ).toBe(true);
    dispose();
  });

  it("keeps a long number inside the plot and wraps a long name", () => {
    const { root, dispose } = mount(() => (
      <Bars
        label="Requests"
        series={SERIES}
        categories={["a category with a long name"]}
        values={[[40, 40, 40]]}
      />
    ));
    const cell = cells(root)[0]!;
    // the bar may run under a long label, but the label never starts past the cell:
    // `min()` caps the padding, so no part of the value is clipped
    expect(start(cell)).toBeLessThan(cell.getBoundingClientRect().width);
    expect(getComputedStyle(cell).overflowWrap).toBe("anywhere");
    const name = root.querySelector<HTMLElement>('th[scope="row"]')!;
    expect(getComputedStyle(name).overflowWrap).toBe("anywhere");
    expect(name.textContent).toBe("a category with a long name");
    dispose();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
